// ratelimit.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// A Limiter must be constructed with New; the zero value is not usable.
type Limiter struct {
	mu        sync.Mutex
	rate      float64       // tokens per second
	burst     float64       // bucket capacity
	tokens    float64       // current tokens
	last      time.Time     // last refill time
	clock     Clock
}

var (
	ErrNonPositiveRate  = errors.New("ratelimit: rate must be > 0")
	ErrNonPositiveBurst = errors.New("ratelimit: burst must be > 0")
	ErrNilClock         = errors.New("ratelimit: clock must not be nil")
)

// New returns a Limiter with the given refill rate (tokens per second),
// burst capacity, and clock. If clock is nil, the real clock is used.
func New(rate, burst float64, clock Clock) (*Limiter, error) {
	if rate <= 0 {
		return nil, ErrNonPositiveRate
	}
	if burst <= 0 {
		return nil, ErrNonPositiveBurst
	}
	if clock == nil {
		clock = realClock{}
	}
	return &Limiter{
		rate:   rate,
		burst:  burst,
		tokens: burst,
		clock:  clock,
	}, nil
}

// refill advances the bucket to time t, adding accrued tokens.
// Caller must hold l.mu.
func (l *Limiter) refill(t time.Time) {
	if !t.After(l.last) {
		return
	}
	elapsed := t.Sub(l.last).Seconds()
	l.tokens = min(l.burst, l.tokens+elapsed*l.rate)
	l.last = t
}

// AllowN reports whether n tokens may be consumed at time now.
// If so, the tokens are deducted; otherwise the bucket is unchanged.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill(now)
	need := float64(n)
	if l.tokens >= need {
		l.tokens -= need
		return true
	}
	return false
}

// Allow reports whether one token may be consumed now.
func (l *Limiter) Allow() bool {
	return l.AllowN(l.clock.Now(), 1)
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}
