		{"zero burst", 1, 0, newFakeClock(), ErrNonPositiveBurst},
		{"negative burst", 1, -5, newFakeClock(), ErrNonPositiveBurst},
		{"nil clock", 1, 1, nil, ErrNilClock},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			_, err := New(tc.rate, tc.burst, tc.clock)
			if err != tc.wantErr {
				t.Fatalf("New(%v, %v, %v) error = %v, want %v", tc.rate, tc.burst, tc.clock, err, tc.wantErr)
			}
		})
	}
	if _, err := New(1, 1, nil); err != nil {
		t.Errorf("New with nil clock should default to real clock, got %v", err)
	}
}

