			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 2, true},   // consume full burst
				{0, 1, false},  // empty
				{time.Second, 1, true},  // 1 token refilled
				{0, 1, false},           // only 1 was available
